-- Service divisions & services
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_websites', 'websites', 'Websites & Web Applications', 'Business websites, online stores and custom web applications that load fast and are easy to update.', '<p>We design and build websites for organisations that need more than a brochure. Every site is designed for phones first, loads quickly on mobile data, is set up for search and, from the Business Website up, lets your team update content without calling us.</p><p>For larger needs we build web applications on the same foundations: secure sign-in, role-based access, a database built around your records and local payment options.</p>', '[{"title":"Fast on real networks","body":"Pages are built to load quickly on mobile data, with optimised images and minimal scripts."},{"title":"Easy to update","body":"Business and e-commerce sites include a content editor so your team can change text and images."},{"title":"Found on search","body":"Clean structure, metadata, a sitemap and Search Console setup so people can find you."},{"title":"Ready to take payments","body":"Accept EcoCash, OneMoney, InnBucks and cards through Paynow when you sell online."}]', '["Mobile-first design for phones, tablets and desktops","Contact form and WhatsApp button","On-page SEO basics and an SSL certificate","Content editing on Business and E-commerce sites","Handover notes, and training where the package includes it"]', '[{"q":"Can I update the website myself?","a":"Yes, from the Business Website up. Those sites include a content editor and a short training session at handover. The Starter Website has no editor; we make changes for you during the support period."},{"q":"How long does a website take?","a":"A Starter Website takes 5 to 7 working days, a Business Website 2 to 3 weeks and an online store 4 to 6 weeks, once we have your content. Custom web applications are scheduled in the written quotation."},{"q":"Who owns the website?","a":"You do. On full payment, the content, design and code we wrote for you are yours, as set out in our service terms."}]', 'globe', 'active', 1, 10, 'Websites & Web Applications', 'Starter and business websites, e-commerce stores and custom web applications for organisations in Zimbabwe. Fast, mobile-first and easy to update.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_websites__starter_website', 'scat_websites', 'starter-website', 'Starter Website', 'Up to 5 pages: a professional presence for a new or small business.', 'fixed', 15000, 'USD', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_websites__business_website', 'scat_websites', 'business-website', 'Business Website', 'Up to 12 pages with a content editor, blog, analytics and search setup.', 'fixed', 32000, 'USD', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_websites__ecommerce_website', 'scat_websites', 'ecommerce-website', 'E-commerce Website', 'An online store with cart, checkout and local payment methods.', 'starting_from', 65000, 'USD', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_websites__custom_web_applications', 'scat_websites', 'custom-web-applications', 'Custom Web Applications', 'Logins, dashboards, a database and business logic, scoped in a written quotation.', 'starting_from', 120000, 'USD', 'active', 40);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_business_software', 'business-software', 'Business Software & Systems', 'POS, inventory, ERP and reporting systems shaped around how your organisation works.', '<p>Off-the-shelf software often forces you to change how you work. We build business systems around your processes instead: point of sale and stock control, full business management platforms and the dashboards that show how the business is doing.</p><p>Systems support multiple branches and currencies, keep an audit trail of changes and can connect to the tools you already use.</p>', '[{"title":"Fits your process","body":"Workflows, approvals and reports follow how your team already works."},{"title":"Multi-currency by design","body":"USD and ZWG amounts are kept separate and reported correctly."},{"title":"Clear audit trail","body":"Every important change records who did it and when."},{"title":"Grows in stages","body":"Start with the module you need most and add others as you grow."}]', '["Process mapping and requirements document","Web-based system with role-based access","Data migration from spreadsheets or existing systems","Reports and exports","Staff training and user guides"]', '[{"q":"Can you move our data from spreadsheets?","a":"Yes. Data migration is part of most projects. We clean and import your existing records and check the totals with you before go-live."},{"q":"Does it work across branches?","a":"Yes. Systems can run across several branches with each user seeing only what their role allows."}]', 'layers', 'active', 1, 20, 'Business Software: POS, ERP & Reporting Systems', 'POS and inventory systems, custom ERP and business management platforms, and reporting dashboards built around your processes.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_business_software__pos', 'scat_business_software', 'pos', 'POS & Inventory Systems', 'Fast checkout, stock control and daily reconciliation for shops and counters.', 'starting_from', 80000, 'USD', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_business_software__erp', 'scat_business_software', 'erp', 'Custom ERP & Business Management Systems', 'One system for sales, purchasing, stock, finance and people.', 'starting_from', 250000, 'USD', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_business_software__dashboards_reporting', 'scat_business_software', 'dashboards-reporting', 'Business Dashboards & Reporting Systems', 'One screen with the numbers your team checks every day, and scheduled reports.', 'starting_from', 60000, 'USD', 'active', 30);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_cross_platform_apps', 'cross-platform-apps', 'Cross-Platform Application Development', 'One codebase for Android, iOS, Windows, macOS and Linux, built for real networks and real devices.', '<p>We build one application from a single codebase and release it on the platforms your users have: Android, iOS, Windows, macOS and Linux. One codebase keeps the cost of building and maintaining the app down while every platform gets the same features.</p><p>Apps are designed for the devices people actually use, including mid-range Android phones and patchy connections, and can keep working offline and sync when a connection returns.</p>', '[{"title":"One codebase, five platforms","body":"Android, iOS, Windows, macOS and Linux from the same code, so features ship everywhere together."},{"title":"Offline-capable","body":"Apps can keep working without signal and sync data when the connection returns."},{"title":"Store-ready","body":"We prepare listings, screenshots and releases for the app stores you publish to."},{"title":"Connected to your systems","body":"Apps talk to your existing databases, payment methods and business software through secure APIs."}]', '["User experience and interface design","One application released for the platforms you choose","Back-end API and admin dashboard where needed","Testing on real devices","App store publishing support"]', '[{"q":"Which platforms are supported?","a":"Android, iOS, Windows, macOS and Linux. You choose which ones to release on first; adding another later reuses the same code."},{"q":"Can the app work without internet?","a":"Yes. Offline support is planned during design so data is stored safely on the device and synced later."}]', 'smartphone', 'active', 1, 30, 'Cross-Platform App Development: Android, iOS & Desktop', 'One codebase for Android, iOS, Windows, macOS and Linux apps, with offline support, app store publishing and secure back-ends.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_cross_platform_apps__cross_platform_development', 'scat_cross_platform_apps', 'cross-platform-development', 'Cross-Platform Application Development', 'One codebase released on Android, iOS, Windows, macOS and Linux.', 'starting_from', 120000, 'USD', 'active', 10);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_ai_data', 'ai-data', 'AI, Data & Intelligence', 'Practical AI assistants, analytics and document processing that answer real business questions.', '<p>Most organisations already hold the data they need to make better decisions; it is just spread across systems and spreadsheets. We bring it together, clean it and present it in a form your team will use.</p><p>Where AI helps, we add it in practical ways: assistants that answer questions from your own documents, extraction of data from invoices and forms, and analysis of your history.</p>', '[{"title":"Decisions from facts","body":"Analysis built on clean, reconciled data from your own systems."},{"title":"Less manual capture","body":"Document processing extracts data from forms, receipts and invoices."},{"title":"Practical AI","body":"Assistants and automations are scoped to clear tasks, with human review where it matters."},{"title":"Your data stays yours","body":"We design for privacy and follow Zimbabwe’s Cyber and Data Protection Act."}]', '["Data audit and connection to your sources","AI assistant, analysis or document-processing workflow","Scheduled reports","Documentation of data flows and access"]', '[{"q":"Do we need a lot of data to use AI?","a":"Not always. Many useful features, such as document extraction or a question-answering assistant over your policies, work with the documents you already have."},{"q":"Is our data shared with anyone?","a":"Only with the services the solution needs to run, under agreements that protect it. We explain where your data goes in the written proposal."}]', 'line-chart', 'active', 1, 40, 'AI Integration, Data Intelligence & Document Processing', 'AI assistants built on your own content, data intelligence and analytics, and intelligent document processing for invoices and forms.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_ai_data__ai_applications', 'scat_ai_data', 'ai-applications', 'AI Integration & Intelligent Assistants', 'Assistants that answer questions from your own content, added to your website or systems.', 'starting_from', 50000, 'USD', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_ai_data__data_analytics', 'scat_ai_data', 'data-analytics', 'Data Intelligence & Analytics', 'Analysis of your sales, operations and customer data, brought together in one place.', 'starting_from', 60000, 'USD', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_ai_data__document_processing', 'scat_ai_data', 'document-processing', 'Intelligent Document Processing', 'Extract data from invoices, forms and receipts automatically.', 'starting_from', 80000, 'USD', 'active', 30);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_automation_integration', 'automation-integration', 'Automation & Integration', 'Workflows, payment gateways, APIs and integrations that remove manual steps between systems.', '<p>When systems do not talk to each other, people re-type data, chase approvals and reconcile by hand. We connect your systems through APIs and automate the repetitive steps in between.</p><p>We work with Zimbabwean payment rails, including EcoCash, OneMoney, InnBucks, O’mari and card payments, and build integrations that confirm every payment before it is recorded.</p>', '[{"title":"Fewer manual steps","body":"Automated workflows move data and approvals without re-typing."},{"title":"Reliable payments","body":"Gateway integrations verify every payment with the provider before marking it paid."},{"title":"Systems that agree","body":"Integrations keep records consistent across your tools."},{"title":"Room to change","body":"Clean, documented APIs make it easier to swap or add systems later."}]', '["Integration design and documentation","Automated workflows and notifications","Payment integration with confirmation and reconciliation","APIs with authentication","Error alerts and safe retries"]', '[{"q":"Can you add EcoCash and card payments to our existing website?","a":"Yes. Each local method (EcoCash, OneMoney, InnBucks or O’mari) is $50 and card payments are $100, including payment confirmation and receipts."},{"q":"What happens if an integration fails?","a":"Integrations retry safely and alert your team, so nothing is lost or processed twice."}]', 'workflow', 'active', 1, 50, 'Automation, Payment Gateway Integration & APIs', 'Business process automation, payment gateway integration for EcoCash, OneMoney, InnBucks, O’mari and cards, API development and systems integration.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_automation_integration__process_automation', 'scat_automation_integration', 'process-automation', 'Business Process Automation', 'Automate approvals, reminders and hand-offs between teams, priced per workflow.', 'starting_from', 40000, 'USD', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_automation_integration__payment_gateways', 'scat_automation_integration', 'payment-gateways', 'Payment Gateway Integration', 'EcoCash, OneMoney, InnBucks and O’mari at $50 per method; card payments at $100.', 'fixed', 5000, 'USD', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_automation_integration__api_development', 'scat_automation_integration', 'api-development', 'API Development', 'Secure, documented APIs for your apps, partners and systems.', 'starting_from', 40000, 'USD', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, price_minor, currency, status, sort_order) VALUES ('svc_automation_integration__systems_integration', 'scat_automation_integration', 'systems-integration', 'Systems Integration', 'Connect accounting, CRM and the other systems you rely on so records agree.', 'starting_from', 50000, 'USD', 'active', 40);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_add_ons', 'add-ons', 'Add-ons', 'Extra pages, logo design, copywriting, languages and catalogue uploads to add to a website package.', '<p>Add-ons extend a website package when you need a little more: extra pages, a logo, text written for you, another language or more products loaded into your store. Each one has a fixed published price.</p>', '[]', '[]', '[]', 'sparkles', 'active', 0, 60, 'Website Add-ons', 'Additional website pages, logo design, copywriting, additional languages and product catalogue uploads at fixed prices.');
