INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_retail_wholesale', 'retail-wholesale', 'Retail & Wholesale', 'Point of sale, stock control and online ordering for shops, distributors and wholesalers.', '[{"title":"Stock that does not match the shelves","body":"Sales, deliveries and transfers recorded in different places make it hard to know what is actually in stock."},{"title":"Many ways to pay","body":"Customers pay with cash, EcoCash, OneMoney, InnBucks, cards and bank transfers, and each needs reconciling."},{"title":"Several branches, one picture","body":"Owners need daily sales and stock figures from every branch without waiting for end-of-month reports."}]', '<p>We build point-of-sale and inventory systems that record every sale and stock movement once, reconcile mobile money and card payments, and give owners a daily view across branches. For businesses that sell online, we add a store or ordering portal connected to the same stock.</p>', 'wallet', 'published', 10, 'Retail & Wholesale · Kuzikode Intelligent Technologies', 'POS, inventory, e-commerce and payment integration for retailers and wholesalers in Zimbabwe.');
