INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_financial_services', 'financial-services', 'Financial Services & Microfinance', 'Loan management, client portals and secure integrations for microfinance institutions and financial service providers.', '[{"title":"Manual loan tracking","body":"Applications, disbursements and repayments kept in spreadsheets are slow to update and easy to get wrong."},{"title":"Security and audit expectations","body":"Financial data needs role-based access, audit trails and careful handling of personal information."},{"title":"Collecting repayments","body":"Clients want to repay with mobile money, and every payment has to be matched to the right account."}]', '<p>We build loan and client management systems with clear approval workflows, repayment schedules and audit logs, plus portals where clients can see their balances. Repayments can be collected through mobile money and card gateways and reconciled automatically.</p>', 'shield-check', 'published', 20, 'Financial Services & Microfinance · Kuzikode Intelligent Technologies', 'Loan management, client portals and payment integration for microfinance and financial services.');
