INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_education', 'education', 'Education', 'Fees, student records and parent communication for schools, colleges and training providers.', '[{"title":"Collecting and tracking fees","body":"Fee payments arrive through several channels and must be matched to the right learner and term."},{"title":"Keeping parents informed","body":"Notices, results and statements are often sent on paper or through scattered messaging groups."},{"title":"Records in many places","body":"Enrolment, attendance and results kept in separate files make reporting slow."}]', '<p>We build school management systems and parent portals that bring enrolment, fees, results and communication together. Parents can view statements and pay fees online, and administrators get up-to-date reports without re-typing data.</p>', 'layers', 'published', 30, 'Education · Kuzikode Intelligent Technologies', 'School management systems, parent portals and online fee payments for education providers.');
