INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_healthcare', 'healthcare', 'Healthcare', 'Appointments, patient records and billing for clinics, pharmacies and practices.', '[{"title":"Busy front desks","body":"Phone bookings and paper diaries lead to double bookings, long queues and missed appointments."},{"title":"Sensitive information","body":"Patient information must be protected with strict access control and handled in line with data protection law."},{"title":"Billing and medical aid","body":"Invoices, cash payments and medical aid claims need to be tracked together."}]', '<p>We build booking, patient record and billing systems designed around privacy: role-based access, audit trails and encrypted connections. Clinics can offer online booking and reminders, and pharmacies can manage stock and dispensing in one place.</p>', 'life-buoy', 'published', 40, 'Healthcare · Kuzikode Intelligent Technologies', 'Appointment booking, patient records and billing systems for clinics and pharmacies.');
