INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_ngos_development', 'ngos-development', 'NGOs & Development', 'Data collection, beneficiary records and donor reporting for NGOs and development programmes.', '[{"title":"Field data on paper","body":"Survey and distribution data collected on paper is slow to capture and hard to check."},{"title":"Donor reporting","body":"Each donor wants indicators in a different format, and compiling them takes days."},{"title":"Limited connectivity","body":"Field teams often work where the network is weak or unavailable."}]', '<p>We build mobile data collection apps that work offline and sync when a connection returns, beneficiary and programme databases, and dashboards that turn field data into donor-ready reports.</p>', 'globe', 'published', 50, 'NGOs & Development · Kuzikode Intelligent Technologies', 'Offline data collection apps, beneficiary databases and donor reporting dashboards for NGOs.');
