INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_hospitality_tourism', 'hospitality-tourism', 'Hospitality & Tourism', 'Direct bookings, guest communication and operations for lodges, hotels and tour operators.', '[{"title":"Relying on third-party booking sites","body":"Commission on every booking adds up, and guests cannot easily book directly."},{"title":"Taking payments from abroad","body":"International guests expect to pay by card, while local guests prefer mobile money."},{"title":"Coordinating operations","body":"Rooms, activities, transfers and staff schedules are often managed separately."}]', '<p>We build websites with direct booking and online payments, and back-office tools for reservations, activities and guest communication, so you can sell more directly and run each day from one place.</p>', 'sparkles', 'published', 60, 'Hospitality & Tourism · Kuzikode Intelligent Technologies', 'Booking websites, online payments and reservation tools for hotels, lodges and tour operators.');
