INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_agriculture', 'agriculture', 'Agriculture', 'Farm records, supply chains and grower payments for farms, cooperatives and agri-businesses.', '[{"title":"Tracking inputs and yields","body":"Inputs, labour and harvests recorded in notebooks make it hard to see what each field really costs and produces."},{"title":"Paying many growers","body":"Cooperatives and contractors need accurate records of deliveries, deductions and payments for each grower."},{"title":"Planning ahead","body":"Decisions on planting, stock and sales are easier with reliable history to look back on."}]', '<p>We build farm and cooperative management systems for inputs, deliveries, grower accounts and payments, with mobile apps for field teams and dashboards that show trends across seasons.</p>', 'line-chart', 'published', 70, 'Agriculture · Kuzikode Intelligent Technologies', 'Farm management, grower payment and supply-chain systems for agriculture in Zimbabwe.');
