INSERT OR IGNORE INTO industries (id, slug, name, summary, challenges, body, icon, status, sort_order, seo_title, seo_description) VALUES ('ind_logistics_transport', 'logistics-transport', 'Logistics & Transport', 'Dispatch, tracking and fleet records for transporters, couriers and logistics companies.', '[{"title":"Knowing where every load is","body":"Customers want updates, and dispatchers spend hours on the phone finding out where trucks are."},{"title":"Paperwork on every trip","body":"Waybills, proof of delivery and fuel records are easily lost or delayed."},{"title":"Costs per vehicle","body":"Fuel, maintenance and driver costs need to be tracked per vehicle and per trip."}]', '<p>We build dispatch and fleet systems with driver apps for proof of delivery, customer tracking pages and cost reports per vehicle and route, connected to your invoicing.</p>', 'workflow', 'published', 80, 'Logistics & Transport · Kuzikode Intelligent Technologies', 'Dispatch, proof-of-delivery apps and fleet cost tracking for logistics and transport companies.');
