-- FAQ
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_general_who', 'general', 'Who do you work with?', 'Small and medium businesses, NGOs, schools, clinics and other organisations in Zimbabwe and across Africa that need a website, an app or a business system.', 10, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_general_remote', 'general', 'Can you work with us if we are outside Zimbabwe?', 'Yes. We work remotely with video calls, shared documents and the client portal, wherever you are based.', 20, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_general_start', 'general', 'How do we get started?', 'Use the Start a project form or the contact page to tell us what you need. We reply, usually within one business day, with questions or a written quotation.', 30, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_general_ownership', 'general', 'Who owns the website or software you build?', 'Once you have paid in full, you own the deliverables we created specifically for you, including the code and content. Third-party software keeps its own licence. Our service terms explain the details.', 40, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_projects_timeline', 'projects', 'How long does a project take?', 'It depends on the scope. Each package shows a typical delivery time, and every quotation includes a timeline with milestones. Timelines also depend on receiving content and decisions on time.', 50, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_projects_content', 'projects', 'Do you write the content and provide images?', 'You know your business best, so we usually work from your content. We can also write copy for an extra fee, and help you choose suitable images.', 60, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_projects_updates', 'projects', 'How will we know how the project is going?', 'We post updates every week in your client portal, where you can also see milestones, files, quotations and invoices.', 70, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_projects_changes', 'projects', 'What if we want changes during the project?', 'Small changes within the agreed scope are part of the revision rounds. Larger changes are quoted separately before we start them, so the budget never changes without your agreement.', 80, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_projects_existing', 'projects', 'Can you improve a system or website we already have?', 'Yes. We can review what you have, recommend whether to improve it or replace it, and move your data across if needed.', 90, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_support_after', 'support', 'What happens after launch?', 'Every project includes a support period. After that, you can ask us for help by the hour or agree ongoing support in a quotation.', 100, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_support_request', 'support', 'How do I ask for help?', 'Clients can open a support request in the client portal and follow it there. You can also contact us by email or phone.', 110, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_support_backups', 'support', 'Is my data backed up?', 'Systems we build that hold business data are set up with regular backups, and we test that backups can be restored.', 120, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_careers_open', 'careers', 'Are you hiring?', 'Open roles are listed on our careers page when we have them. You can apply online for each role.', 130, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_careers_cv', 'careers', 'Can I send my CV if there is no open role?', 'We only consider applications for advertised roles, so that every applicant gets a proper review. Check the careers page for openings.', 140, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_careers_privacy', 'careers', 'What happens to my application data?', 'We use it only to consider your application. CVs are deleted 12 months after the role closes, as described in our privacy policy.', 150, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_quote', 'pricing', 'Is the price on a package final?', 'Package prices are a clear starting point. We confirm the final scope and price in a written quotation before any work starts, so you know exactly what you are paying for.', 160, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_currency', 'pricing', 'Which currency do you charge in?', 'Our prices are in US dollars. If you need to pay in ZWG, ask for it when you request a quotation and we will confirm the amount on the quotation.', 170, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_payment_methods', 'pricing', 'How can I pay?', 'Invoices can be paid online on our checkout page with EcoCash, OneMoney, InnBucks or card (as available), or by bank transfer. You get a receipt by email as soon as a payment is confirmed.', 180, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_deposit', 'pricing', 'Do I pay everything upfront?', 'No. Projects are usually billed by milestone. Where a deposit is agreed in the quotation, work starts once it is received, and the balance is invoiced as milestones are approved.', 190, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_third_party', 'pricing', 'What about third-party costs?', 'Third-party costs, such as app store fees or payment gateway transaction fees, are paid by you and listed in the quotation before work starts.', 200, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_changes', 'pricing', 'What if I need something that is not in a package?', 'Add-ons such as additional pages, logo design, copywriting, additional languages or a product catalogue upload can be added to any website package. For anything else, describe what you need and we will quote it separately before we start.', 210, 1);
INSERT OR IGNORE INTO faqs (id, category, question, answer, sort_order, published) VALUES ('faq_pricing_vat', 'pricing', 'Do prices include VAT?', 'Prices exclude VAT where applicable. Any tax that applies is shown as a separate line on the quotation and invoice.', 220, 1);

