INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_home__process', 'pag_home', 'process', 'process', 50, 1, '{"title":"How we work","steps":[{"title":"Discover","body":"We learn how your organisation works and agree what success looks like."},{"title":"Design","body":"We plan the structure and design the screens before writing code."},{"title":"Build","body":"We build in milestones and show you progress every week."},{"title":"Launch","body":"We test, migrate your data, train your team and go live."},{"title":"Support","body":"We stay on hand to fix, improve and keep things running."}],"link":{"label":"More about how we work","href":"/how-we-work"}}', '{"title":"How we work","steps":[{"title":"Discover","body":"We learn how your organisation works and agree what success looks like."},{"title":"Design","body":"We plan the structure and design the screens before writing code."},{"title":"Build","body":"We build in milestones and show you progress every week."},{"title":"Launch","body":"We test, migrate your data, train your team and go live."},{"title":"Support","body":"We stay on hand to fix, improve and keep things running."}],"link":{"label":"More about how we work","href":"/how-we-work"}}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_home__values', 'pag_home', 'values', 'values', 60, 1, '{"title":"What we value","items":[{"title":"Excellence","body":"We do careful work and check it before it reaches you."},{"title":"Integrity","body":"We say what we can do, price it honestly and keep our word."},{"title":"Customer commitment","body":"Your goals set the priorities, and we stay with you after launch."}],"link":{"label":"About Kuzikode","href":"/about"}}', '{"title":"What we value","items":[{"title":"Excellence","body":"We do careful work and check it before it reaches you."},{"title":"Integrity","body":"We say what we can do, price it honestly and keep our word."},{"title":"Customer commitment","body":"Your goals set the priorities, and we stay with you after launch."}],"link":{"label":"About Kuzikode","href":"/about"}}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
