INSERT OR IGNORE INTO website_pages (id, key, title, seo_title, seo_description, status, published_at) VALUES ('pag_about', 'about', 'About', 'About Kuzikode Intelligent Technologies', 'Kuzikode Intelligent Technologies is a Zimbabwe-based technology company that designs, builds and runs digital solutions for businesses and organisations.', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__overview', 'pag_about', 'overview', 'rich_text', 10, 1, '{"title":"About Kuzikode","html":"<p>Kuzikode Intelligent Technologies is a technology company based in Zimbabwe. We design, build and run digital solutions for businesses, organisations and individuals: websites and web applications, business software, cross-platform apps, data and AI tools, and the automations and integrations that connect them.</p><p>We work as a long-term technology partner rather than a one-off supplier. That means clear scope before we start, regular updates while we build, and support once the work is live.</p>"}', '{"title":"About Kuzikode","html":"<p>Kuzikode Intelligent Technologies is a technology company based in Zimbabwe. We design, build and run digital solutions for businesses, organisations and individuals: websites and web applications, business software, cross-platform apps, data and AI tools, and the automations and integrations that connect them.</p><p>We work as a long-term technology partner rather than a one-off supplier. That means clear scope before we start, regular updates while we build, and support once the work is live.</p>"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__story', 'pag_about', 'story', 'rich_text', 20, 1, '{"title":"Our story","html":"<p>Kuzikode started from a simple observation: many organisations in Zimbabwe run on spreadsheets, paper and tools that do not talk to each other, while the software built for other markets rarely fits local payment methods, currencies and networks.</p><p>We set out to build technology that fits. That means accepting EcoCash and cards, handling USD and ZWG correctly, working on mobile data, and being simple enough for busy teams to use every day.</p>"}', '{"title":"Our story","html":"<p>Kuzikode started from a simple observation: many organisations in Zimbabwe run on spreadsheets, paper and tools that do not talk to each other, while the software built for other markets rarely fits local payment methods, currencies and networks.</p><p>We set out to build technology that fits. That means accepting EcoCash and cards, handling USD and ZWG correctly, working on mobile data, and being simple enough for busy teams to use every day.</p>"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__mission', 'pag_about', 'mission', 'statement', 30, 1, '{"title":"Mission","body":"To empower businesses and organisations through accessible, intelligent and dependable technology solutions that solve real-world problems."}', '{"title":"Mission","body":"To empower businesses and organisations through accessible, intelligent and dependable technology solutions that solve real-world problems."}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__vision', 'pag_about', 'vision', 'statement', 40, 1, '{"title":"Vision","body":"To become a leading African technology company, creating impactful digital solutions that contribute to business growth and technological advancement."}', '{"title":"Vision","body":"To become a leading African technology company, creating impactful digital solutions that contribute to business growth and technological advancement."}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__values', 'pag_about', 'values', 'values', 50, 1, '{"title":"Core values","items":[{"title":"Excellence","body":"We hold our work to a high standard and test it properly. Small details matter to the people who use it every day."},{"title":"Innovation","body":"We use new technology where it solves a real problem, not for its own sake."},{"title":"Integrity","body":"We are honest about scope, cost and timelines, and we keep our commitments."},{"title":"Customer commitment","body":"Our clients’ goals set our priorities. We stay involved after launch so the work keeps delivering."},{"title":"Continuous growth","body":"We keep learning, improve how we work after every project and help our clients grow their own capability."}]}', '{"title":"Core values","items":[{"title":"Excellence","body":"We hold our work to a high standard and test it properly. Small details matter to the people who use it every day."},{"title":"Innovation","body":"We use new technology where it solves a real problem, not for its own sake."},{"title":"Integrity","body":"We are honest about scope, cost and timelines, and we keep our commitments."},{"title":"Customer commitment","body":"Our clients’ goals set our priorities. We stay involved after launch so the work keeps delivering."},{"title":"Continuous growth","body":"We keep learning, improve how we work after every project and help our clients grow their own capability."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__objectives', 'pag_about', 'objectives', 'list', 60, 1, '{"title":"Objectives","items":["Deliver reliable websites, apps and business systems that organisations use every day.","Make local payment methods and multi-currency records work properly in the software we build.","Help organisations move from paper and spreadsheets to connected digital processes.","Build lasting client relationships through clear communication and dependable support.","Develop our own products for African small and medium businesses."]}', '{"title":"Objectives","items":["Deliver reliable websites, apps and business systems that organisations use every day.","Make local payment methods and multi-currency records work properly in the software we build.","Help organisations move from paper and spreadsheets to connected digital processes.","Build lasting client relationships through clear communication and dependable support.","Develop our own products for African small and medium businesses."]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_about__approach', 'pag_about', 'approach', 'rich_text', 70, 1, '{"title":"Our approach to technology and problem-solving","html":"<p>We start with the problem, not the tool. Before proposing anything we learn how your team works, where time is lost and what a good outcome looks like.</p><p>We then choose proven technology that suits your budget, your users and the networks they rely on. We build in small milestones, show working software early and adjust based on what we learn.</p><p>Security, data protection and maintainability are part of the build from day one: role-based access, audit trails, backups and documentation come as standard.</p>"}', '{"title":"Our approach to technology and problem-solving","html":"<p>We start with the problem, not the tool. Before proposing anything we learn how your team works, where time is lost and what a good outcome looks like.</p><p>We then choose proven technology that suits your budget, your users and the networks they rely on. We build in small milestones, show working software early and adjust based on what we learn.</p><p>Security, data protection and maintainability are part of the build from day one: role-based access, audit trails, backups and documentation come as standard.</p>"}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_pages (id, key, title, seo_title, seo_description, status, published_at) VALUES ('pag_services', 'services', 'Services', 'Services · Kuzikode Intelligent Technologies', 'Websites and web applications, business software, cross-platform apps, AI and data, and automation and integration, with published prices.', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
