INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_how_we_work__process', 'pag_how_we_work', 'process', 'process', 20, 1, '{"title":"Our process","steps":[{"title":"Discover","body":"We learn how your organisation works, who will use the solution and what success looks like, then agree the scope in writing."},{"title":"Design","body":"We plan the structure and design the key screens with you before development starts, so there are no surprises."},{"title":"Build","body":"We build in milestones, share progress every week in your client portal and ask for your approval at each milestone."},{"title":"Launch","body":"We test thoroughly, move your data across, train your team and go live when you are ready."},{"title":"Support","body":"We stay on hand after launch to fix issues, make improvements and keep everything secure and up to date."}]}', '{"title":"Our process","steps":[{"title":"Discover","body":"We learn how your organisation works, who will use the solution and what success looks like, then agree the scope in writing."},{"title":"Design","body":"We plan the structure and design the key screens with you before development starts, so there are no surprises."},{"title":"Build","body":"We build in milestones, share progress every week in your client portal and ask for your approval at each milestone."},{"title":"Launch","body":"We test thoroughly, move your data across, train your team and go live when you are ready."},{"title":"Support","body":"We stay on hand after launch to fix issues, make improvements and keep everything secure and up to date."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_how_we_work__engagement', 'pag_how_we_work', 'engagement', 'features', 30, 1, '{"title":"Ways to work with us","intro":"Choose the model that fits the work. We will recommend one when we read your brief.","items":[{"icon":"list-checks","title":"Fixed-price package","body":"A defined package such as a business website or an online store, with a clear list of what is included."},{"icon":"layers","title":"Fixed-scope project","body":"A custom project scoped in a written quotation, with milestones and a price agreed before we start."},{"icon":"gauge","title":"Time and materials","body":"For evolving or exploratory work, billed by the hour against an agreed budget, with time reports you can see."},{"icon":"life-buoy","title":"Retainer","body":"A monthly block of hours for ongoing improvements, support and maintenance."}]}', '{"title":"Ways to work with us","intro":"Choose the model that fits the work. We will recommend one when we read your brief.","items":[{"icon":"list-checks","title":"Fixed-price package","body":"A defined package such as a business website or an online store, with a clear list of what is included."},{"icon":"layers","title":"Fixed-scope project","body":"A custom project scoped in a written quotation, with milestones and a price agreed before we start."},{"icon":"gauge","title":"Time and materials","body":"For evolving or exploratory work, billed by the hour against an agreed budget, with time reports you can see."},{"icon":"life-buoy","title":"Retainer","body":"A monthly block of hours for ongoing improvements, support and maintenance."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_how_we_work__expect', 'pag_how_we_work', 'expect', 'values', 40, 1, '{"title":"What you can expect","items":[{"title":"Weekly updates","body":"Progress, decisions and next steps posted in your client portal every week."},{"title":"Milestone-based payments","body":"You pay as agreed milestones are delivered, and can pay invoices online with mobile money or card."},{"title":"You own what we build for you","body":"Once paid in full, the code and content created specifically for you are yours, as set out in our service terms."},{"title":"Straight answers","body":"If something will take longer or cost more, we tell you early and explain why, before any extra work starts."}]}', '{"title":"What you can expect","items":[{"title":"Weekly updates","body":"Progress, decisions and next steps posted in your client portal every week."},{"title":"Milestone-based payments","body":"You pay as agreed milestones are delivered, and can pay invoices online with mobile money or card."},{"title":"You own what we build for you","body":"Once paid in full, the code and content created specifically for you are yours, as set out in our service terms."},{"title":"Straight answers","body":"If something will take longer or cost more, we tell you early and explain why, before any extra work starts."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_how_we_work__quality', 'pag_how_we_work', 'quality', 'list', 50, 1, '{"title":"Quality and security practices","items":["Code reviewed and tested automatically before every release.","Accessibility checked against WCAG 2.1 AA.","Encrypted connections, hashed passwords and role-based access in every system we build.","Two-factor authentication for administrator accounts.","Audit logs for sensitive actions such as payments and permission changes.","Regular backups, with restores tested.","Personal information handled in line with Zimbabwe''s Cyber and Data Protection Act."]}', '{"title":"Quality and security practices","items":["Code reviewed and tested automatically before every release.","Accessibility checked against WCAG 2.1 AA.","Encrypted connections, hashed passwords and role-based access in every system we build.","Two-factor authentication for administrator accounts.","Audit logs for sensitive actions such as payments and permission changes.","Regular backups, with restores tested.","Personal information handled in line with Zimbabwe''s Cyber and Data Protection Act."]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
