INSERT OR IGNORE INTO products (id, slug, name, tagline, description, status, interest_form_enabled, sort_order, published) VALUES ('prd_business_suite', 'business-suite', 'Kuzikode Business Suite', 'Integrated business management for African SMEs.', 'An integrated platform we are developing for small and medium businesses: sales and point of sale, stock, finance, people and customer management in one place, built for local payment methods and multi-currency trading. It is in development and not yet available.', 'in_development', 1, 10, 0);

